}

_helper_mvn_plugin_prefixes() {
    local pom
    pom="$(_argc_util_path_search_parent pom.xml)"
    [[ -n "$pom" ]] || return 0
    _helper_mvn_xml_section "$pom" plugins artifactId |
        sed -e 's/^maven-//' -e 's/-maven-plugin$//' -e 's/-plugin$//' |
        while IFS= read -r prefix; do
            [[ -n "$prefix" ]] || continue
            printf '%s\0\n' "$prefix:"
        done
}

_helper_mvn_xml_section() {
    local file="$1" section="$2" tag="$3"
    [[ -f "$file" ]] || return 0
    gawk -v SECTION="$section" -v TAG="$tag" '
        function trim(s) {
            sub(/^[ \t\r\n]+/, "", s)
            sub(/[ \t\r\n]+$/, "", s)
            return s
        }
        BEGIN { RS = "<"; depth = 0; inside = 0 }
        {
            rec = $0
            if (rec == "") { next }
            if (substr(rec, 1, 1) == "/") {
                name = trim(substr(rec, 2, index(rec, ">") - 2))
                if (depth > 0 && stack[depth] == name) {
                    if (name == SECTION) { inside = 0 }
                    depth--
                }
                next
            }
            pos = index(rec, ">")
            if (pos == 0) { next }
            head = substr(rec, 1, pos - 1)
            text = trim(substr(rec, pos + 1))
            if (substr(head, length(head)) == "/") { next }
            name = head
            sub(/[ \t\r\n].*$/, "", name)
            if (name == SECTION) { inside = 1 }
            if (inside && name == TAG && text != "") { print text }
            depth++
            stack[depth] = name
        }
    ' "$file"
}
